package com.crms.controller;import com.crms.entity.*;import com.crms.enums.*;import com.crms.repository.*;import jakarta.validation.constraints.NotNull;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api") public class ApplicationController{private final ApplicationRepository apps;private final StudentRepository students;private final JobRepository jobs;private final UserRepository users;public ApplicationController(ApplicationRepository a,StudentRepository s,JobRepository j,UserRepository u){apps=a;students=s;jobs=j;users=u;}@PostMapping("/applications")public ResponseEntity<?> apply(@RequestBody ApplyRequest r,Authentication a){var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();var s=students.findByUserId(u.getId()).orElseThrow();var j=jobs.findById(r.jobId()).orElseThrow();if(j.getStatus()!=JobStatus.OPEN)return ResponseEntity.badRequest().body(Map.of("message","Job is not open"));if(apps.existsByStudentIdAndJobId(s.getId(),j.getId()))return ResponseEntity.status(409).body(Map.of("message","You have already applied"));if(j.getMinCgpa()!=null&&(s.getCgpa()==null||s.getCgpa()<j.getMinCgpa()))return ResponseEntity.badRequest().body(Map.of("message","You do not meet the CGPA requirement"));if(j.getGraduationYear()!=null&&(s.getGraduationYear()==null||!j.getGraduationYear().equals(s.getGraduationYear())))return ResponseEntity.badRequest().body(Map.of("message","You do not meet the graduation year requirement"));if(j.getMaxBacklogs()!=null&&(s.getBacklogs()==null||s.getBacklogs()>j.getMaxBacklogs()))return ResponseEntity.badRequest().body(Map.of("message","You do not meet the backlog requirement"));var x=new Application();x.setStudent(s);x.setJob(j);return ResponseEntity.status(201).body(view(apps.save(x)));}@GetMapping("/applications/my")public List<Map<String,Object>> mine(Authentication a){return apps.findByStudentUserId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId()).stream().map(this::view).toList();}@GetMapping("/jobs/{jobId}/applications")public List<Map<String,Object>> byJob(@PathVariable Long jobId,Authentication a){var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();var j=jobs.findById(jobId).orElseThrow();if(!j.getCompany().getOwner().getId().equals(u.getId())&&u.getRole()!=Role.ADMIN&&u.getRole()!=Role.PLACEMENT_OFFICER)throw new org.springframework.security.access.AccessDeniedException("Not authorized");return apps.findByJobId(jobId).stream().map(this::view).toList();}@PatchMapping("/applications/{id}/status")public Map<String,Object> status(@PathVariable Long id,@RequestBody StatusRequest r,Authentication a){var x=apps.findById(id).orElseThrow();var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(!x.getJob().getCompany().getOwner().getId().equals(u.getId())&&u.getRole()!=Role.ADMIN&&u.getRole()!=Role.PLACEMENT_OFFICER)throw new org.springframework.security.access.AccessDeniedException("Not authorized");x.setStatus(r.status());return view(apps.save(x));}private Map<String,Object> view(Application x){return Map.of("id",x.getId(),"status",x.getStatus().name(),"createdAt",x.getCreatedAt().toString(),"jobTitle",x.getJob().getTitle(),"companyName",x.getJob().getCompany().getName());}public record ApplyRequest(@NotNull Long jobId){}public record StatusRequest(@NotNull ApplicationStatus status){}}
